async def act(page):
    """
    From the current page state (home page), navigate to the Sample Page where the site's
    search UI is expected to live, perform a visible search for the keyword 'DeepSeek',
    wait for results to render in the main region, and click the bottom-most result.

    Notes:
    - We avoid calling the site-aware helper create_curated_collection_by_search because that
      helper always begins with `await page.goto('/')` which would reset us to the root page
      where, in earlier attempts, a complementary region was not present. Calling it now would
      likely reintroduce that failure. Therefore we drive the visible UI directly from the
      current state.
    - All locators use accessibility-role-centric selectors (get_by_role) and we count
      before .nth() to avoid indexing errors.
    - The final action is a click on the bottom result (a link inside the last article if
      present, otherwise the article container). That click is the last action because it
      will likely navigate away.
    """

    # 1) Navigate to the Sample Page (relative goto). This is safe and does not rely on
    # clicking a link (clicking would also navigate, but we reserve navigation as the last action
    # only for the final click). Using relative goto is allowed and predictable.
    await page.goto("/?page_id=2")
    await page.wait_for_load_state("networkidle")

    # 2) Try to locate the complementary region which commonly houses the site's search UI.
    comp = None
    try:
        comp_locator = page.get_by_role("complementary")
        if await comp_locator.count() > 0:
            # Use the first complementary region
            comp = comp_locator.nth(0)
            # Wait a short time for it to become visible
            try:
                await comp.wait_for(state="visible", timeout=3000)
            except Exception:
                # proceed even if not visible yet; we'll still attempt to find controls inside
                pass
    except Exception:
        comp = None

    # 3) Locate a usable search input. Prefer role=searchbox, fallback to role=textbox.
    search_input = None
    # Prefer search input inside complementary region when available
    if comp is not None:
        try:
            sb = comp.get_by_role("searchbox")
            if await sb.count() > 0:
                search_input = sb.nth(0)
        except Exception:
            search_input = None

        if search_input is None:
            try:
                tb = comp.get_by_role("textbox")
                if await tb.count() > 0:
                    search_input = tb.nth(0)
            except Exception:
                search_input = None

    # If we still haven't found a search input, fall back to looking globally on the page.
    if search_input is None:
        try:
            global_sb = page.get_by_role("searchbox")
            if await global_sb.count() > 0:
                search_input = global_sb.nth(0)
        except Exception:
            search_input = None

    if search_input is None:
        try:
            global_tb = page.get_by_role("textbox")
            if await global_tb.count() > 0:
                search_input = global_tb.nth(0)
        except Exception:
            search_input = None

    # If no search input was discovered, we cannot continue.
    if search_input is None:
        return

    # 4) Fill the search input with the required keyword.
    await search_input.fill("DeepSeek")

    # 5) Attempt to trigger the search. Preferred: button with visible name that includes 'Search'.
    triggered = False
    # Prefer a button inside the complementary region
    if comp is not None:
        try:
            # get_by_role name lookup is case-insensitive substring by default
            search_btns = comp.get_by_role("button", name="Search")
            if await search_btns.count() > 0:
                await search_btns.nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # If not triggered yet, try any visible button in the complementary region
    if not triggered and comp is not None:
        try:
            any_btns = comp.get_by_role("button")
            if await any_btns.count() > 0:
                await any_btns.nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # If still not triggered, try a global 'Search' button
    if not triggered:
        try:
            global_search_btns = page.get_by_role("button", name="Search")
            if await global_search_btns.count() > 0:
                await global_search_btns.nth(0).click()
                triggered = True
        except Exception:
            triggered = False

    # Last-resort: press Enter in the search input
    if not triggered:
        try:
            await search_input.press("Enter")
            triggered = True
        except Exception:
            triggered = False

    # If we couldn't trigger a search, there's nothing further we can do reliably.
    if not triggered:
        return

    # 6) Wait for results area (role="main") to appear. Use a visible wait then networkidle fallback.
    main = None
    try:
        main_locator = page.get_by_role("main")
        if await main_locator.count() > 0:
            main = main_locator.nth(0)
            try:
                await main.wait_for(state="visible", timeout=5000)
            except Exception:
                # fallback to networkidle
                await page.wait_for_load_state("networkidle")
    except Exception:
        # fallback to networkidle and then attempt to get main
        try:
            await page.wait_for_load_state("networkidle")
            main_locator = page.get_by_role("main")
            if await main_locator.count() > 0:
                main = main_locator.nth(0)
        except Exception:
            main = None

    if main is None:
        return

    # 7) Collect role="article" children inside main and click the bottom-most one.
    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count == 0:
        # No article results to click
        return

    last_index = article_count - 1
    target_article = articles.nth(last_index)

    # Prefer clicking a link inside the article
    links = target_article.get_by_role("link")
    try:
        links_count = await links.count()
    except Exception:
        links_count = 0

    if links_count > 0:
        # Final action: click the first link inside the bottom-most article
        await links.nth(0).click()
    else:
        # Final action: click the article container itself
        await target_article.click()

